import csv
rows = list(csv.DictReader(open("bench/results/summary.csv")))
f = lambda k: [float(r[k]) for r in rows]
for k in ("skew","tail_excess","autocorr_lag1","outlier_share","drift"):
    v = f(k); print(k, min(v), max(v))
mm = [(float(r["mean"])-float(r["median"]))/float(r["median"]) for r in rows]; print("mean-med", min(mm), max(mm))
print("max shapiro p", max(f("shapiro_p_normal")), max(f("shapiro_p_lognormal")))
for r in rows: print(r["implementation"], r["workload"], r["recording_s"], r["better_fit"], round(float(r["drift"]),3))
`);
const rg = await $`python3 ${sp}/ranges.py`.text();
await Read({file_path: `${sp}/time-light.png`}); await Read({file_path: `${sp}/dist-light.png`});
rg

